import { test, expect } from '@playwright/test';

test.describe('Billing Address Change During Checkout', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the checkout page
    await page.goto('/checkout');

    // Wait for the page to load
    await page.waitForLoadState('networkidle');
  });

  test('should display current billing address on checkout page', async ({ page }) => {
    // Verify that the billing address section is visible
    const billingAddressSection = page.getByRole('region', { name: /billing address/i });
    await expect(billingAddressSection).toBeVisible();

    // Verify that the current address is displayed
    const currentAddress = page.getByText(/123 Main Street/i);
    await expect(currentAddress).toBeVisible();
  });

  test('should allow user to change billing address', async ({ page }) => {
    // Click on the "Change Address" or "Edit" button
    const editButton = page.getByRole('button', { name: /change|edit.*address/i });
    await editButton.click();

    // Wait for the address form to appear
    await page.waitForSelector('form[data-testid="billing-address-form"]', { timeout: 5000 });

    // Clear the street address field and enter new address
    const streetInput = page.getByLabel(/street address/i);
    await streetInput.clear();
    await streetInput.fill('456 Oak Avenue');

    // Clear the city field and enter new city
    const cityInput = page.getByLabel(/city/i);
    await cityInput.clear();
    await cityInput.fill('San Francisco');

    // Clear the state field and enter new state
    const stateInput = page.getByLabel(/state|province/i);
    await stateInput.clear();
    await stateInput.fill('CA');

    // Clear the zip code field and enter new zip code
    const zipInput = page.getByLabel(/zip|postal code/i);
    await zipInput.clear();
    await zipInput.fill('94102');

    // Click the "Save Address" or "Confirm" button
    const saveButton = page.getByRole('button', { name: /save|confirm|update.*address/i });
    await saveButton.click();

    // Wait for the form to close and address to update
    await page.waitForTimeout(1000);

    // Verify the new address is displayed
    const updatedAddress = page.getByText(/456 Oak Avenue/i);
    await expect(updatedAddress).toBeVisible();

    const updatedCity = page.getByText(/San Francisco/i);
    await expect(updatedCity).toBeVisible();
  });

  test('should validate required fields when changing billing address', async ({ page }) => {
    // Click on the "Change Address" button
    const editButton = page.getByRole('button', { name: /change|edit.*address/i });
    await editButton.click();

    // Wait for the address form to appear
    await page.waitForSelector('form[data-testid="billing-address-form"]', { timeout: 5000 });

    // Clear the street address field
    const streetInput = page.getByLabel(/street address/i);
    await streetInput.clear();

    // Clear the city field
    const cityInput = page.getByLabel(/city/i);
    await cityInput.clear();

    // Try to save without filling required fields
    const saveButton = page.getByRole('button', { name: /save|confirm|update.*address/i });
    await saveButton.click();

    // Verify validation error messages appear
    const streetError = page.getByText(/street address is required/i);
    await expect(streetError).toBeVisible();

    const cityError = page.getByText(/city is required/i);
    await expect(cityError).toBeVisible();
  });

  test('should cancel billing address change and keep original address', async ({ page }) => {
    // Get the original address text
    const originalAddress = await page.getByText(/123 Main Street/i).textContent();

    // Click on the "Change Address" button
    const editButton = page.getByRole('button', { name: /change|edit.*address/i });
    await editButton.click();

    // Wait for the address form to appear
    await page.waitForSelector('form[data-testid="billing-address-form"]', { timeout: 5000 });

    // Modify the address
    const streetInput = page.getByLabel(/street address/i);
    await streetInput.clear();
    await streetInput.fill('999 Temporary Street');

    // Click the "Cancel" button
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await cancelButton.click();

    // Wait for the form to close
    await page.waitForTimeout(500);

    // Verify the original address is still displayed
    const addressAfterCancel = page.getByText(/123 Main Street/i);
    await expect(addressAfterCancel).toBeVisible();

    // Verify the temporary address is not displayed
    const tempAddress = page.getByText(/999 Temporary Street/i);
    await expect(tempAddress).not.toBeVisible();
  });

  test('should update billing address and reflect changes in order summary', async ({ page }) => {
    // Click on the "Change Address" button
    const editButton = page.getByRole('button', { name: /change|edit.*address/i });
    await editButton.click();

    // Wait for the address form to appear
    await page.waitForSelector('form[data-testid="billing-address-form"]', { timeout: 5000 });

    // Update the address fields
    const streetInput = page.getByLabel(/street address/i);
    await streetInput.clear();
    await streetInput.fill('789 Pine Road');

    const cityInput = page.getByLabel(/city/i);
    await cityInput.clear();
    await cityInput.fill('Los Angeles');

    const stateInput = page.getByLabel(/state|province/i);
    await stateInput.clear();
    await stateInput.fill('CA');

    const zipInput = page.getByLabel(/zip|postal code/i);
    await zipInput.clear();
    await zipInput.fill('90001');

    // Save the new address
    const saveButton = page.getByRole('button', { name: /save|confirm|update.*address/i });
    await saveButton.click();

    // Wait for the update to complete
    await page.waitForTimeout(1000);

    // Verify the order summary shows the updated address
    const orderSummary = page.getByRole('region', { name: /order summary|summary/i });
    await expect(orderSummary).toBeVisible();

    const summaryAddress = orderSummary.getByText(/789 Pine Road/i);
    await expect(summaryAddress).toBeVisible();

    const summaryCity = orderSummary.getByText(/Los Angeles/i);
    await expect(summaryCity).toBeVisible();
  });
});
